import { readFileSync } from 'node:fs';
const root='/home/df/.codex/worktrees/aa39/puni-00/tools/tool-fleet/src';
const path=root+'/lab-staging-native-control.test.ts';
const harness=readFileSync(path,'utf8');
const cold=readFileSync(root+'/lab-staging-native-cold-fixture.py','utf8');
const start=harness.indexOf('const coldWorker = readFileSync(');
const end=harness.indexOf('\n);',start)+4;
const boundary='\n# Worker entry follows the runtime provider.\n';
for(const [name,payload] of [ ['oversized',cold+'#'.repeat(8193-cold.length)], ['missing',cold.replace(boundary,'\n')], ['duplicate',cold+boundary] ]) {
  for(const omitted of [false,true]) {
    let source=harness.slice(0,start)+'const coldWorker = '+JSON.stringify(payload)+';'+harness.slice(end);
    source=source.replaceAll('import.meta.url',JSON.stringify('file://'+path));
    const guardStart=source.indexOf('if (\n  Buffer.byteLength(coldWorker)');
    const guardEnd=source.indexOf('\nconst runtimeProvider',guardStart);
    if(omitted)source=source.slice(0,guardStart)+source.slice(guardEnd);
    source=source.replace('const runtimeProvider = coldWorker.slice(0, providerEnd);',"const runtimeProvider = coldWorker.slice(0, providerEnd);\nthrow new Error('EXERCISE provider extraction reached');");
    const file='/tmp/puni-task120-evidence/cap-'+name+'-'+String(omitted)+'.test.ts';
    await Bun.write(file,source);
    const child=Bun.spawnSync(['bun','test',file],{stdout:'pipe',stderr:'pipe',timeout:5000});
    const output=child.stdout.toString()+child.stderr.toString();
    const expected=omitted?'EXERCISE provider extraction reached':'bounded cold fixture must contain exactly one runtime-provider boundary';
    if(child.exitCode===0 || !output.includes(expected))throw new Error(name+' '+omitted+' unexpected: '+output);
    console.log(name+' '+(omitted?'omission EXERCISE':'protected refusal')+' bytes='+Buffer.byteLength(payload));
  }
}
